  String? _error;
  @override void initState() { super.initState(); reload(); }
  Future<void> reload() async { setState(() => _loading = true); try { final data = await _service.list(); if (mounted) setState(() { _budgets = data; _error = null; _loading = false; }); } on ApiException catch (e) { if (mounted) setState(() { _error = e.message; _loading = false; }); } }
