  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const FingoBrand(compact: true), actions: [IconButton(onPressed: reload, tooltip: 'Actualizar presupuestos', icon: const Icon(Icons.refresh))]), floatingActionButton: FloatingActionButton.extended(onPressed: () => _edit(), icon: const Icon(Icons.add), label: const Text('Nuevo')), body: SafeArea(child: ListView(padding: const EdgeInsets.fromLTRB(20, 10, 20, 100), children: [Text('Presupuestos', style: Theme.of(context).textTheme.headlineMedium), const SizedBox(height: 6), Text('Planifica tus límites y sigue tu progreso.', style: Theme.of(context).textTheme.bodySmall), const SizedBox(height: 20), if (_loading) const Center(child: Padding(padding: EdgeInsets.all(32), child: CircularProgressIndicator())) else if (_error != null) Center(child: Column(children: [Text(_error!, textAlign: TextAlign.center), TextButton(onPressed: reload, child: const Text('Reintentar'))])) else if (_budgets.isEmpty) Card(child: Padding(padding: const EdgeInsets.all(24), child: Column(children: [const Icon(Icons.account_balance_wallet_outlined, size: 42, color: FingoColors.accent), const SizedBox(height: 12), const Text('Aún no tienes presupuestos'), const SizedBox(height: 12), ElevatedButton(onPressed: () => _edit(), child: const Text('Crear el primero'))]))) else ..._budgets.map(_card)])));
